-- Node: mono-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Acute Monoarthritis Hub — Rule Out the Septic Joint","body":"**⚠️ 5 DO NOT MISS:**\n1. **Septic arthritis** — a joint that is infected today can be destroyed in days. This is the diagnosis you must exclude in EVERY acute monoarthritis.\n2. **Disseminated gonococcal infection** — young, sexually active; migratory arthritis, tenosynovitis, pustular rash.\n3. **Prosthetic joint infection** — any hot prosthetic joint is infected until proven otherwise; do not tap without ortho.\n4. **Crystal arthropathy that hides an infection** — gout and septic arthritis can coexist; crystals do not rule out infection.\n5. **Trauma with fracture / hemarthrosis** — especially anticoagulated patients; do not miss a fracture.\n\n**The one question that drives this entire hub: is this joint SEPTIC?** Because a missed septic joint means cartilage destruction, osteomyelitis, sepsis, and disability, the acute monoarthritis pathway is built around excluding infection first. Arthrocentesis is the answer to most of these patients. [1,2]\n\n**Scan in 30 seconds:** [1]\n- **The joint** — single hot, red, swollen, exquisitely painful joint with pain on any passive motion? That is septic arthritis until the tap says otherwise.\n- **Systemic signs** — fever, rigors, tachycardia, hypotension (septic joint can seed the blood).\n- **Prosthesis or recent joint procedure/injection** — changes everything; involve ortho, do not tap blindly.\n- **Immunocompromise / diabetes / IVDU / RA** — raises septic risk and can blunt the exam.\n- **Skin** — overlying cellulitis (can mimic and complicate), pustular/vesicular rash (gonococcal), tophi (gout), psoriasis.\n\n**The 4 questions that change the differential:** [1,2]\n1. **Is the joint prosthetic or recently instrumented?** (do not tap without ortho; PJI pathway)\n2. **Fever or systemic illness?** (raises septic + gonococcal probability)\n3. **Prior identical attacks that self-resolved in days?** (favors crystal — but does NOT exclude infection)\n4. **Trauma, or anticoagulated with a swollen joint?** (fracture / hemarthrosis)","citation":[1,2,7,9],"next":"mono-exclusions","summary":"The whole hub is built to exclude the SEPTIC joint. Arthrocentesis answers most patients. A prosthetic/instrumented joint is infected until proven otherwise — involve ortho, do not tap blindly.","safetyLevel":"critical"}'::jsonb
WHERE id = 'mono-start' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-exclusions (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Time-Critical Exclusions — Pick the One That Fits","body":"Infection first, always. Each branch routes to a deep-dive and the next action.","citation":[1,2,3,7,9],"options":[{"label":"Hot single joint + fever / systemic illness, native joint","description":"Septic arthritis — arthrocentesis NOW, then empiric antibiotics","next":"mono-exc-septic","urgency":"critical"},{"label":"Prosthetic joint or recent surgery/injection, now hot and painful","description":"Prosthetic joint infection — do NOT tap blindly; ortho first","next":"mono-exc-prosthetic","urgency":"critical"},{"label":"Young, sexually active + migratory arthritis / tenosynovitis / pustular rash","description":"Disseminated gonococcal infection — ceftriaxone, cultures, STI workup","next":"mono-exc-gono","urgency":"urgent"},{"label":"Recurrent self-limited attacks, 1st MTP / knee / wrist, tophi or CPPD history","description":"Crystal arthropathy — but confirm and never assume it excludes infection","next":"mono-exc-crystal","urgency":"urgent"},{"label":"Trauma, or anticoagulated with a tense swollen joint","description":"Fracture / hemarthrosis — imaging, reverse coagulopathy if needed","next":"mono-exc-trauma","urgency":"urgent"},{"label":"Tick exposure / endemic area + knee monoarthritis, subacute","description":"Lyme arthritis — serology; still tap to exclude infection if acute/hot","next":"mono-exc-lyme"},{"label":"None of the above — acute monoarthritis, stable, undifferentiated","description":"Initial bundle + arthrocentesis decision","next":"mono-rescue"}],"summary":"Infection first. Each branch links to its deep-dive + the next action. Crystals never exclude sepsis.","safetyLevel":"critical"}'::jsonb
WHERE id = 'mono-exclusions' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-exc-septic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Septic Arthritis — Tap Then Treat","body":"Open [Septic Arthritis](#/tree/septic-arthritis) for the full diagnostic + antibiotic + drainage pathway, and [Joint Arthrocentesis](#/tree/joint-arthrocentesis) for the procedure.\n\n**A native hot joint with fever is septic arthritis until synovial fluid says otherwise.** No single feature rules it in or out — the joint aspirate is the test. Delay in drainage causes irreversible cartilage loss. [2]\n\n**Next 5 minutes:**\n- **Arthrocentesis BEFORE antibiotics when feasible** (do not delay antibiotics in a septic-appearing patient, but get the tap first if you can). Send synovial fluid for cell count + differential, Gram stain, culture, and crystals.\n- Synovial WBC interpretation: higher counts raise probability (often >50,000/mm3 with PMN predominance, but septic arthritis can occur at lower counts — no cutoff excludes it). Gram stain positive in only ~30-50%.\n- Blood cultures × 2, CBC, CMP, CRP/ESR, lactate; type/screen if septic.\n- **Empiric IV antibiotics** after the tap: cover Staph aureus (including MRSA — vancomycin) + gram-negatives per risk; add ceftriaxone if gonococcal possible.\n- **Orthopedic/surgical consult for joint drainage** (arthroscopic/open washout or serial aspiration) — antibiotics alone do not clear a septic joint.\n- Do not inject steroids into a possibly infected joint.\n\n🛑 Never withhold antibiotics/drainage waiting for confirmatory culture in a septic-appearing joint. 🛑 A positive crystal analysis does NOT exclude co-existent infection — treat both if the picture fits.","citation":[2,9,10],"recommendation":"Arthrocentesis first (cell count, Gram stain, culture, crystals), blood cultures, then empiric IV antibiotics (cover MRSA), and orthopedic consult for drainage. Crystals do not exclude infection.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'mono-exc-septic' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-exc-prosthetic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Prosthetic Joint — Do Not Tap Blindly","body":"A hot, painful prosthetic joint (or one recently operated/injected) is a prosthetic joint infection until proven otherwise — and the workup differs from a native joint. [3]\n\n**Next steps:**\n- **Consult orthopedics BEFORE aspirating.** ED aspiration of a prosthetic joint risks seeding the prosthesis and is often best done by orthopedics under sterile/image-guided conditions with their input on antibiotic timing.\n- **Do NOT start empiric antibiotics reflexively** if the patient is stable and cultures are pending — premature antibiotics can render prosthetic-joint cultures falsely negative and complicate management. Exception: a septic/unstable patient gets antibiotics after cultures.\n- Send blood cultures, CBC, CRP, ESR (CRP/ESR are useful screening tests for PJI).\n- X-ray the joint (loosening, lucency).\n- Analgesia, immobilize, admit per orthopedics.\n\n🛑 Do NOT perform a blind ED arthrocentesis of a prosthetic joint without orthopedic involvement. 🛑 Avoid empiric antibiotics before cultures in a STABLE prosthetic-joint patient — it sabotages the diagnostic workup.","citation":[3,13],"recommendation":"Orthopedics FIRST for a hot prosthetic joint — do not tap blindly. Send blood cultures + CRP/ESR + X-ray. Hold empiric antibiotics in the stable patient until cultures obtained; give them if septic.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'mono-exc-prosthetic' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-exc-gono (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Disseminated Gonococcal Infection","body":"Disseminated gonococcal infection (DGI) is a leading cause of acute arthritis in young, sexually active adults and presents two ways: (1) the classic triad of migratory polyarthralgia, tenosynovitis, and dermatitis (pustular/vesiculopustular lesions), or (2) a purulent monoarthritis. [4]\n\n**Next steps:**\n- **Arthrocentesis** if an effusion is present — send cell count, Gram stain (often negative in DGI), culture; synovial fluid NAAT for N. gonorrhoeae where available.\n- **NAAT of urethral/cervical/rectal/pharyngeal sites + blood cultures** — the diagnosis is often made from mucosal sites, not the joint.\n- **Empiric ceftriaxone 1 g IV/IM daily** (per current CDC guidance) plus treatment for possible chlamydia co-infection.\n- Screen for other STIs (HIV, syphilis, chlamydia); counsel + partner notification.\n- Still cannot fully exclude Staph septic arthritis — if the joint is frankly purulent, cover accordingly and drain.\n\n🛑 Gram stain and even synovial culture are frequently negative in DGI — diagnose from mucosal NAAT + clinical picture; do not let a negative joint Gram stain reassure you.","citation":[4,8],"recommendation":"Suspect DGI in young sexually active patients with migratory arthritis + tenosynovitis + pustular rash. Tap the joint, NAAT all mucosal sites + blood cultures, empiric ceftriaxone, full STI workup. Joint Gram stain is often negative.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'mono-exc-gono' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-exc-crystal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Crystal Arthropathy — Confirm, Never Assume","body":"Gout and pseudogout (CPPD) are the most common causes of acute monoarthritis, but the ED trap is assuming crystal disease and missing an infected joint — the two coexist. [5]\n\n**Open [Gout](#/tree/gout)** for the acute-flare treatment and chronic pathway, and [Approach to Arthritis](#/tree/approach-to-arthritis) for the broader differential and synovial-fluid interpretation.\n\n**Recognize:**\n- **Gout** — rapid-onset, exquisitely painful, often 1st MTP (podagra), midfoot, ankle, or knee; tophi; hyperuricemia (may be normal during a flare). Negatively birefringent needle-shaped monosodium urate crystals.\n- **Pseudogout (CPPD)** — older patients, knee/wrist, chondrocalcinosis on X-ray. Positively birefringent rhomboid calcium pyrophosphate crystals.\n\n**Next steps:**\n- **Arthrocentesis with crystal analysis AND cell count/Gram stain/culture** whenever infection cannot be confidently excluded — especially with fever, very high inflammatory markers, or a first attack.\n- Treat the flare: NSAIDs, colchicine, or corticosteroids (intra-articular only after infection excluded; otherwise systemic).\n- **If any doubt about infection, treat as septic until cultures return** — crystals present + infection present is a real and dangerous combination.\n\n🛑 A history of gout does NOT exclude a septic joint in this attack. 🛑 Positive crystals + high synovial WBC + fever → still tap for culture and consider empiric antibiotics.","citation":[5,11],"recommendation":"Confirm crystals by aspiration but ALWAYS send cell count/Gram stain/culture too. Treat the flare (NSAIDs/colchicine/steroids). If infection cannot be excluded, treat as septic until cultures return.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'mono-exc-crystal' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-exc-trauma (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Trauma / Hemarthrosis","body":"A swollen joint after trauma — or a spontaneously swollen joint in an anticoagulated or bleeding-disorder patient — points to fracture, ligamentous injury, or hemarthrosis rather than infection or crystals. [1]\n\n**Next steps:**\n- **X-ray** the joint (fracture, effusion, lipohemarthrosis — a fat-fluid level indicates intra-articular fracture). CT/MRI for occult fracture or internal derangement as indicated.\n- **Anticoagulated / hemophiliac:** consider spontaneous hemarthrosis — check coags, reverse if bleeding is significant ([Anticoagulation Reversal](#/tree/anticoag-reversal)); for hemophilia, replace the deficient factor early ([Hemophilia](#/tree/hemophilia)).\n- Arthrocentesis if the diagnosis is unclear or infection is possible — bloody aspirate suggests hemarthrosis; fat globules suggest intra-articular fracture. Do not aspirate over a fracture unnecessarily.\n- Analgesia, immobilize, ice, elevate; orthopedic follow-up or consult for significant injuries.\n\n🛑 A tense hemarthrosis in a hemophiliac needs factor replacement BEFORE or with any procedure — do not delay. 🛑 Do not attribute a swollen joint to “trauma” and miss a co-existent infection if there are systemic signs — tap if in doubt.","citation":[1,12],"recommendation":"X-ray for fracture/effusion (lipohemarthrosis = intra-articular fracture). Reverse coagulopathy / replace factor for hemarthrosis. Immobilize + analgesia + ortho follow-up. Tap if infection cannot be excluded.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'mono-exc-trauma' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-rescue (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Initial Bundle — Undifferentiated Acute Monoarthritis","body":"No clear life-threat branch fits, but infection still must be excluded. Standard ED bundle centered on the joint aspirate: [1,2]\n\n**THE BUNDLE:**\n- **IV access + monitor** if febrile/systemically ill; analgesia (acetaminophen ± NSAID if no contraindication, or opioid for severe pain).\n- **Arthrocentesis is the pivotal test** — for any effusion where infection is on the differential (see Module 4 for the decision). Send synovial fluid for: cell count + differential, Gram stain, culture, crystal analysis. (Glucose/protein add little.)\n- **Blood work:** CBC, CMP, CRP, ESR, uric acid (limited value acutely), blood cultures × 2 if febrile or septic-appearing; β-hCG if reproductive-age female before certain drugs/imaging.\n- **X-ray** the joint (fracture, chondrocalcinosis, erosions, effusion).\n- **STI/gonococcal screen** if the demographic/history fits.\n- **Do NOT inject intra-articular steroid** until infection is excluded.\n- Analgesia, immobilize/support, elevate.\n\n**Reassess after the tap results:** synovial cell count + Gram stain steer you toward septic vs inflammatory/crystal vs non-inflammatory, and toward disposition.","citation":[1,2,7,9],"next":"mono-rescue-reassess","summary":"Analgesia + arthrocentesis (cell count, Gram stain, culture, crystals) + CBC/CRP/ESR + blood cultures if febrile + X-ray + STI screen if fits. No intra-articular steroid until infection excluded.","safetyLevel":"warning"}'::jsonb
WHERE id = 'mono-rescue' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-rescue-reassess (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Reassess — What Did the Tap Show?","body":"Interpret the synovial fluid + clinical picture to choose the pathway.","citation":[1,2,9,10],"options":[{"label":"High synovial WBC / positive Gram stain / septic-appearing","description":"Treat as septic — antibiotics + drainage; re-enter exclusions","next":"mono-exc-septic","urgency":"critical"},{"label":"Crystals positive, infection excluded, flare controlled","description":"Crystal arthropathy — discharge with flare treatment + follow-up","next":"mono-dispo-discharge"},{"label":"Inconclusive tap or dry tap, infection not excluded","description":"Imaging / image-guided aspiration; observe pending cultures","next":"mono-imaging","urgency":"urgent"},{"label":"Non-inflammatory fluid, benign picture, systemically well","description":"Likely OA / mechanical / trauma — disposition","next":"mono-dispo"}],"summary":"High WBC/positive Gram stain → treat septic. Crystals + infection excluded → discharge with flare Rx. Inconclusive/dry tap → image + observe pending cultures."}'::jsonb
WHERE id = 'mono-rescue-reassess' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-imaging (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Arthrocentesis & Imaging Decision","body":"Arthrocentesis is the central decision in acute monoarthritis; imaging supports it. [2,7]\n\n**Aspirate the joint when:**\n- Any acute monoarthritis where septic arthritis cannot be confidently excluded (that is most of them)\n- Fever, systemic illness, or an atraumatic hot joint\n- Diagnostic uncertainty (is it crystal or infection?)\n- See [Joint Arthrocentesis](#/tree/joint-arthrocentesis) for landmarks and technique.\n\n**Do NOT aspirate (or defer to specialist) when:**\n- Overlying cellulitis at the needle site (risk of seeding the joint) — choose an alternate approach or ultrasound guidance; involve ortho.\n- Prosthetic joint — orthopedics performs it (see PJI branch).\n- Uncorrected severe coagulopathy — correct first if possible; a difficult tap in a bleeding patient needs weighing.\n\n**Imaging:**\n- **Plain X-ray** — first-line: fracture, chondrocalcinosis (CPPD), erosions (gout/inflammatory), effusion, joint-space narrowing, lipohemarthrosis.\n- **Point-of-care / formal ultrasound** — confirms and localizes an effusion, guides aspiration (especially hip, small joints, or when landmark tap fails). Very useful for a “dry” tap.\n- **MRI** — for suspected osteomyelitis, occult fracture, or when septic arthritis is suspected but the joint cannot be aspirated (e.g., hip, sacroiliac); also for early erosive changes.\n- **CT** — for complex bony anatomy (SI joint, sternoclavicular).\n\n**Synovial fluid interpretation (rough guide):** non-inflammatory (WBC <2,000) = OA/trauma; inflammatory (2,000-50,000) = crystal/inflammatory/early septic; septic (often >50,000, PMN-predominant) — but NO cutoff excludes infection; culture is the arbiter.","citation":[2,7,9,10],"next":"mono-dispo","summary":"Tap almost every acute monoarthritis unless cellulitis overlies the site, the joint is prosthetic, or uncorrected coagulopathy. X-ray first; ultrasound guides a dry tap; MRI for osteomyelitis or an un-aspiratable joint. No synovial WBC cutoff excludes sepsis."}'::jsonb
WHERE id = 'mono-imaging' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-dispo (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Disposition","body":"Disposition follows whether infection is excluded and how the patient looks. Defer to the deep-dive consult once a diagnosis is committed.","citation":[1,2,7],"options":[{"label":"Discharge — infection excluded, benign/crystal cause, pain controlled, reliable","description":"Flare/mechanical treatment + rheumatology or PCP follow-up","next":"mono-dispo-discharge"},{"label":"Observe — cultures pending, inconclusive tap, borderline picture","description":"Short stay / obs for culture results + serial exam","next":"mono-dispo-observe","urgency":"urgent"},{"label":"Admit — septic arthritis, PJI, systemic illness, needs drainage/IV abx","description":"Admit per septic-arthritis / PJI criteria; ortho + IV antibiotics","next":"mono-dispo-admit","urgency":"critical"}],"summary":"Discharge if infection excluded and benign; observe if cultures pending/inconclusive; admit septic arthritis, PJI, or systemic illness for drainage + IV antibiotics."}'::jsonb
WHERE id = 'mono-dispo' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-dispo-discharge (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Discharge — Infection Excluded, Benign Cause","body":"Safe discharge criteria: [1,5]\n\n1. **Septic arthritis reasonably excluded** — non-septic synovial fluid (low WBC, negative Gram stain) OR a confident non-infectious diagnosis, and the patient is systemically well.\n2. **Cause identified/plausible** — crystal flare, osteoarthritis, minor trauma, resolving mechanical process.\n3. **Pain controlled** and the patient can bear weight / use the limb adequately.\n4. **No high-risk features** — no fever, no immunocompromise driving concern, no prosthetic joint, cultures either negative or reliably followed up.\n5. **Follow-up arranged** — rheumatology or primary care; culture-result callback plan for any tap sent.\n\n**Treatment on discharge (crystal flare):** NSAIDs (if no renal/GI/cardiac contraindication), colchicine, or a short oral steroid course; start/adjust urate-lowering therapy in coordination with follow-up (do not start it mid-flare without a plan).\n\n**Written return precautions:**\n- Fever, spreading redness, worsening pain or swelling, inability to move the joint\n- New joints involved, rash, or systemic illness\n\n**Do NOT discharge if:** septic arthritis not excluded, prosthetic joint, fever/systemic illness, immunocompromise with an unclear joint, or unreliable follow-up / no culture callback.","citation":[1,5,7,11],"recommendation":"Discharge only when infection is reasonably excluded and the patient is well: treat the crystal/mechanical cause, arrange rheum/PCP follow-up and culture callback, give clear return precautions.","confidence":"definitive"}'::jsonb
WHERE id = 'mono-dispo-discharge' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-dispo-observe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Observe — Cultures Pending / Inconclusive Tap","body":"Short-stay/observation appropriate when: [2]\n\n- Synovial cell count is intermediate and Gram stain negative, but infection cannot be confidently excluded and cultures are pending\n- A dry or inconclusive tap requiring image-guided re-aspiration\n- Borderline systemic picture (low-grade fever, elevated inflammatory markers) without a clear diagnosis\n- Pain not yet controlled or unable to bear weight, but no firm admission indication\n\n**Observation protocol:**\n- Serial joint and vital-sign checks; watch for evolving fever, spreading erythema, worsening effusion\n- Follow synovial and blood culture results\n- Ultrasound-guided re-aspiration if the initial tap failed and suspicion persists\n- Rheumatology / orthopedics input as needed\n- **Low threshold to start empiric antibiotics + admit** if the patient trends toward septic arthritis\n\n**Discharge from observation** once infection is excluded (negative cultures/reassuring course), pain is controlled, and follow-up is arranged; **admit** if the picture declares itself septic.","citation":[2,7,10],"recommendation":"Observe with serial joint/vital checks and pending cultures; re-aspirate under ultrasound if the tap was dry. Low threshold to start antibiotics and admit if the course trends septic.","confidence":"recommended"}'::jsonb
WHERE id = 'mono-dispo-observe' AND tree_id = 'acute-monoarthritis-hub';

-- Node: mono-dispo-admit (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Admit","body":"Admit when: [2,3]\n\n- **Septic arthritis** (native joint) — IV antibiotics + orthopedic drainage; see [Septic Arthritis](#/tree/septic-arthritis).\n- **Prosthetic joint infection** — orthopedic admission; surgical planning (debridement vs exchange).\n- **Disseminated gonococcal infection** with purulent arthritis or systemic illness — IV ceftriaxone.\n- **Systemic sepsis** from a joint source — resuscitate, IV antibiotics, source control.\n- **Uncontrolled pain**, inability to bear weight, or unsafe home situation with an undifferentiated hot joint.\n- **Immunocompromised** patient with an undiagnosed acute monoarthritis and any concern for infection.\n\n**Service selection:**\n- **Orthopedics** primary for septic native joint (washout) and prosthetic joint infection.\n- **Medicine / Infectious Disease** co-management for antibiotic selection and duration, DGI, and immunocompromised hosts.\n- **Rheumatology** for refractory inflammatory arthritis once infection is excluded.\n- **ICU** for septic shock from a joint source.\n\n**Handoff content:** which joint, native vs prosthetic, synovial fluid results (WBC, Gram stain, crystals), cultures sent, antibiotics given (drug + time), blood cultures, systemic status, and the drainage plan.","citation":[2,3,8,13],"recommendation":"Admit septic arthritis, PJI, DGI with systemic illness, or sepsis from a joint. Orthopedics for drainage; ID for antibiotics; ICU if shock. Give empiric IV antibiotics after cultures for a septic native joint.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'mono-dispo-admit' AND tree_id = 'acute-monoarthritis-hub';

