INSERT INTO tree_citations (tree_id, num, text) VALUES ('acute-monoarthritis-hub', 13, 'McNally M, Sousa R, Wouthuyzen-Bakker M, et al. The EBJIS definition of periprosthetic joint infection. Bone Joint J. 2021;103-B(1):18-25. PMID 33380199. doi:10.1302/0301-620X.103B1.BJJ-2020-1381.R1');

-- Node: arb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Rectal Bleeding — Sick Check First","body":"**⚠️ 4 DO NOT MISS:**\n1. **Brisk lower-GI hemorrhage / hemodynamic compromise** — large-volume BRBPR or clots, tachycardia, hypotension, syncope.\n2. **Upper-GI source masquerading as maroon / BRBPR** — a brisk UGIB can present per rectum; urea:creatinine ratio and NG/rectal exam help.\n3. **Anticoagulated / coagulopathic bleeder** — warfarin, DOAC, antiplatelet, liver disease, or a bleeding disorder turns a minor source into a major bleed.\n4. **Colorectal malignancy / IBD** — do not anchor on \"just hemorrhoids\" in age ≥50, weight loss, altered bowel habits, or bloody diarrhea.\n\n**First 60 seconds:**\n- **General appearance** — pale, diaphoretic, end-of-bed ill vs comfortable and well?\n- **Vitals trend** — tachycardia, hypotension, orthostatic change, narrow pulse pressure.\n- **Quantify the bleed** — streaks on tissue vs clots in the bowl vs continuous per-rectum blood. Ask about melena (points upper).\n- **The 4 screening questions:** (1) How much blood, and is it still happening? (2) On any blood thinner or bleeding disorder? (3) Any lightheadedness, syncope, or chest pain? (4) Vomited blood, or black/tarry stool (upper source)?\n\n**If ANY of:** hypotension, tachycardia, orthostasis, ongoing large-volume bleeding, syncope, or a Hb that is dropping — **start resuscitation in parallel with the workup.** Two large-bore IVs, monitor, type and cross, CBC/coags, hold antithrombotics, GI/surgery on notice. Do not funnel an unstable bleeder down a \"hemorrhoids\" pathway.\n\n**If stable + minor bleeding:** go to Rule In / Rule Out.","citation":[1,2,3],"next":"arb-triage","summary":"Gestalt sick check + vitals/orthostatics + quantify bleed + anticoagulation screen. If unstable: resuscitate in parallel.","safetyLevel":"critical"}'::jsonb
WHERE id = 'arb-start' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-lgib-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Brisk Lower-GI Hemorrhage — Hemodynamic Gate","body":"Large-volume hematochezia with hemodynamic instability is the emergency. **~10-15% of severe \"lower\" bleeds are actually a brisk upper source** — keep UGIB on the list. Hemodynamics, not the color of the blood, drive the pathway.","citation":[3,9],"options":[{"label":"Unstable / ongoing large-volume bleeding / Hb dropping","description":"Resuscitate + urgent GI","next":"arb-lgib-verdict","urgency":"critical"},{"label":"Bleeding stopped, stable vitals, minor volume","description":"Not a brisk LGIB — risk-stratify + move on","next":"arb-lgib-excluded","urgency":"routine"}],"summary":"Hemodynamics drive it. Unstable/ongoing = resuscitate + urgent GI; stopped + stable = risk-stratify.","safetyLevel":"critical"}'::jsonb
WHERE id = 'arb-lgib-entry' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-lgib-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Brisk Lower-GI Hemorrhage — Resuscitate + Treat","body":"Open [Lower GI Bleed](#/tree/lower-gi-bleed) (or the broader [GI Bleed Hub](#/tree/gi-bleed-hub)).\n\n**Next 5 minutes:**\n- Two large-bore IVs, monitor, **type and CROSS**; transfuse to a **restrictive threshold (Hb ~7 g/dL**, higher if active cardiac ischemia).\n- CBC, coags, fibrinogen, lactate; **reverse anticoagulation / correct coagulopathy** per severity.\n- **Rule out an upper source in severe bleeds** — an NG lavage or an urgent upper endoscopy; a markedly elevated urea:creatinine ratio points upper.\n- GI consult for **colonoscopy** (after resuscitation ± rapid purge); **CT angiography** if too brisk/unstable for scope, then IR embolization.\n- Massive transfusion protocol if exsanguinating; surgery if uncontrolled.","citation":[3,4,5,9],"recommendation":"Two large-bore IVs, type and cross, restrictive transfusion (~7), reverse anticoagulation, exclude upper source, GI/CTA/IR.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'arb-lgib-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-lgib-excluded (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Brisk LGIB — Excluded (Stable, Self-Limited)","body":"Bleeding has stopped, vitals are stable, and volume was minor — this is not an active brisk hemorrhage right now. **Risk-stratify with the Oakland score** (toolbar): a score **≤10** identifies low-risk patients who may be considered for safe outpatient management. Any recurrence, hemodynamic change, or dropping Hb re-opens the emergency pathway.\n\nReturn to the hub for the next differential.","citation":[3,9,10,11],"next":"arb-triage","recommendation":"Self-limited + stable; use Oakland score (≤10 = low risk) to guide discharge vs admission. Re-escalate if it recurs.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-lgib-excluded' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-ugib-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Upper-GI Source — Resuscitate + Treat","body":"Open [Upper GI Bleed](#/tree/upper-gi-bleed).\n\n**Next 5 minutes:**\n- Two large-bore IVs, monitor, **type and cross**; restrictive transfusion (Hb ~7).\n- **IV PPI**; if cirrhotic / suspected varices add **octreotide + ceftriaxone** (SBP prophylaxis).\n- Reverse anticoagulation / correct coagulopathy.\n- GI for **upper endoscopy within 24 h** (urgently if unstable / variceal).\n- A negative NG lavage does NOT rule out a post-pyloric source — clinical judgment and endoscopy decide.","citation":[4,14],"recommendation":"Type and cross, restrictive transfusion, IV PPI ± octreotide/ceftriaxone if cirrhotic, urgent upper endoscopy.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'arb-ugib-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-anticoag-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Anticoagulated / Coagulopathic Bleeder — Agent Gate","body":"Identify the agent and the coagulopathy — it changes both the risk and the reversal. Warfarin (INR), DOAC (factor Xa or thrombin inhibitor), antiplatelet, liver disease (synthetic failure), or an inherited bleeding disorder (hemophilia, VWD) each has a specific correction.","citation":[5,15],"options":[{"label":"On anticoagulant/antiplatelet with significant or ongoing bleeding","description":"Reverse / correct per agent","next":"arb-anticoag-verdict","urgency":"urgent"},{"label":"Known bleeding disorder (hemophilia / VWD)","description":"Factor replacement pathway","next":"arb-anticoag-verdict","urgency":"urgent"},{"label":"Not anticoagulated, normal coags, minor bleed","description":"Coagulopathy not the driver — move on","next":"arb-anticoag-excluded","urgency":"routine"}],"summary":"Identify agent/disorder. Significant bleed on a thinner or a factor deficiency = reverse/replace; otherwise move on.","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-anticoag-entry' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-anticoag-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Anticoagulated / Coagulopathic — Reverse + Treat","body":"Open [Anticoagulation Reversal](#/tree/anticoag-reversal) (inherited factor deficiency → [Hemophilia](#/tree/hemophilia)).\n\n**Match reversal to the agent:**\n- **Warfarin** — **4-factor PCC** (weight/INR-dosed) + IV vitamin K 10 mg; FFP only if PCC unavailable.\n- **Dabigatran** — **idarucizumab**.\n- **Apixaban / rivaroxaban** — **andexanet alfa** where available, otherwise 4-factor PCC.\n- **Antiplatelet** — platelet transfusion is generally NOT beneficial for GI bleed (contrast with intracranial); hold the agent.\n- **Liver disease** — vitamin K, correct fibrinogen (cryoprecipitate), targeted product; the INR overestimates bleeding risk.\n- **Hemophilia / VWD** — factor VIII/IX concentrate or desmopressin/VWF per type; hematology now.\n\nResuscitate in parallel (type and cross, restrictive transfusion) and address the anatomic source once corrected.","citation":[3,5,15],"recommendation":"Agent-specific reversal: PCC+vit K (warfarin), idarucizumab (dabigatran), andexanet/PCC (Xa), factor replacement (hemophilia). Then treat the source.","confidence":"definitive","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-anticoag-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-malig-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Malignancy / IBD — Alarm-Feature Gate","body":"Do not anchor on hemorrhoids when alarm features are present. **Red flags:** age ≥50 with new rectal bleeding, unintentional weight loss, iron-deficiency anemia, change in bowel caliber/habits, a palpable rectal mass, a family history of colorectal cancer, or bloody diarrhea with systemic features (IBD flare).","citation":[6,19,20],"options":[{"label":"Alarm features present (age ≥50, weight loss, anemia, mass, bloody diarrhea + systemic)","description":"Work up + specialist referral","next":"arb-malig-verdict","urgency":"urgent"},{"label":"No alarm features, young, well, isolated BRB on tissue","description":"Malignancy/IBD unlikely — move on","next":"arb-malig-excluded","urgency":"routine"}],"summary":"Alarm features (age ≥50, weight loss, anemia, mass, systemic bloody diarrhea) = work up. None = unlikely.","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-malig-entry' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-malig-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Malignancy / IBD — Work Up + Treat","body":"**IBD flare** (known or new): open [IBD Flare](#/tree/ibd-flare) — CBC, CRP, stool studies to exclude infection, IV fluids; steroids per GI for a severe flare; screen for toxic megacolon (distension + systemic toxicity + colonic dilation on plain film → surgical emergency).\n\n**Suspected colorectal malignancy** (mass, iron-deficiency anemia, weight loss, age ≥50): **do NOT clear as hemorrhoids** — arrange **colonoscopy** and GI/surgical referral; treat any bleeding-related anemia; consider [Oncological Emergencies](#/tree/oncological-emergencies) for the actively bleeding or obstructing tumor.\n\n**Universal rule:** new rectal bleeding in age ≥50 (or younger with alarm features) needs a documented plan for **colonoscopy** even if an obvious benign source is found.","citation":[6,18,19,20],"recommendation":"IBD flare → IBD Flare consult + exclude infection/toxic megacolon. Alarm features → colonoscopy referral; never clear age ≥50 bleeding as hemorrhoids alone.","confidence":"definitive","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-malig-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-malig-excluded (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Malignancy / IBD — Low Probability","body":"A young, well patient with no alarm features and clearly benign-appearing bleeding (bright red on tissue only) is low-risk for malignancy or IBD today. **This does not remove the need for age-appropriate colorectal screening**, and any new alarm feature (weight loss, anemia, altered habits) warrants a return and colonoscopy.\n\nReturn to the hub for the next differential.","citation":[6,19,20],"next":"arb-triage","recommendation":"Low probability without alarm features; still ensure age-appropriate screening and return precautions for new alarm features.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-malig-excluded' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-colitis-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Infectious / Ischemic Colitis — Pattern Gate","body":"**Bloody diarrhea + abdominal pain** points at colitis. **Infectious (dysentery):** Shigella, Campylobacter, EHEC (watch for HUS — avoid antibiotics if EHEC suspected), C. difficile, Entamoeba; travel/exposure history matters. **Ischemic colitis:** older / vascular / hypotensive event, sudden LLQ pain then bloody diarrhea, \"thumbprinting\" on imaging.","citation":[7,12],"options":[{"label":"Bloody diarrhea + pain (infectious or ischemic pattern)","description":"Stool workup / imaging + supportive care","next":"arb-colitis-verdict","urgency":"urgent"},{"label":"No diarrhea, no pain, formed stool with BRB","description":"Colitis unlikely — move on","next":"arb-colitis-excluded","urgency":"routine"}],"summary":"Bloody diarrhea + pain = infectious vs ischemic colitis workup. Formed stool + BRB, no pain = unlikely.","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-colitis-entry' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-colitis-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Colitis — Work Up + Treat","body":"Open [Diarrhea](#/tree/diarrhea) for the infectious pathway.\n\n**Infectious colitis:** stool culture + PCR panel, **C. difficile** toxin/PCR, ova & parasites if travel; rehydrate. **Avoid empiric antibiotics if EHEC (Shiga-toxin) is suspected** — they raise the HUS risk; check CBC/smear/renal function for HUS. Treat C. difficile per severity (oral vancomycin / fidaxomicin).\n\n**Ischemic colitis:** usually a clinical + CT diagnosis (segmental wall thickening, \"thumbprinting\"); supportive care, bowel rest, IV fluids, and antibiotics for moderate-severe disease; **surgery for gangrene, perforation, or peritonitis**. Correct the low-flow driver (hypotension, arrhythmia, vasopressors).","citation":[7,12,13],"recommendation":"Infectious → stool studies + rehydration; avoid abx if EHEC (HUS risk). Ischemic → CT + supportive care; surgery for gangrene/perforation.","confidence":"definitive","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-colitis-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-colitis-excluded (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Colitis — Unlikely","body":"Formed stool with bright-red blood and no diarrhea or abdominal pain makes an infectious or ischemic colitis unlikely as the driver. If diarrhea, fever, or pain develops, come back and work the colitis pathway.\n\nReturn to the hub for the next differential.","citation":[7,12],"next":"arb-triage","recommendation":"Colitis unlikely without diarrhea/pain; reassess if diarrhea, fever, or pain develops.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-colitis-excluded' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-benign-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Benign Anorectal — Exam Gate","body":"The commonest source of BRBPR is benign anorectal disease, but it is a **diagnosis of exclusion in anyone with alarm features or age ≥50**. Inspect and perform a digital rectal exam (± anoscopy): **hemorrhoids** (painless bright-red blood coating stool / on tissue), **anal fissure** (severe pain with defecation + a posterior-midline tear), **rectal prolapse** (protruding mucosa).","citation":[8,16,17],"options":[{"label":"Prolapse present","description":"Reduce + refer","next":"arb-benign-verdict","urgency":"urgent"},{"label":"Hemorrhoids / fissure, benign exam, no alarm features","description":"Conservative management + follow-up","next":"arb-benign-excluded","urgency":"routine"}],"summary":"Inspect + DRE ± anoscopy. Prolapse = reduce/refer; hemorrhoids/fissure with benign exam + no alarms = conservative.","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-benign-entry' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-benign-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Rectal Prolapse — Reduce + Refer","body":"Open [Rectal Prolapse Reduction](#/tree/rectal-prolapse-reduction).\n\n- **Reduce** the prolapse promptly (manual pressure ± topical sugar to reduce edema) to prevent incarceration / strangulation; analgesia and procedural sedation if needed.\n- Assess viability — a **non-reducible, dusky, or strangulated prolapse is a surgical emergency**.\n- Arrange colorectal surgery follow-up; screen for the underlying cause (chronic straining, pelvic-floor dysfunction) and treat constipation → [Constipation](#/tree/constipation).","citation":[16],"recommendation":"Reduce early to prevent strangulation; surgical emergency if non-reducible/ischemic; colorectal referral + treat constipation.","confidence":"definitive","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-benign-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-benign-excluded (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Benign Anorectal — Conservative Management","body":"Hemorrhoids or an anal fissure in a well patient with a benign exam and **no alarm features**: reassure and treat conservatively — high-fiber diet, adequate fluids, stool softeners, sitz baths, topical agents (and for a chronic fissure, topical nifedipine or nitroglycerin); manage the underlying constipation → [Constipation](#/tree/constipation).\n\n**The safety net:** benign anorectal disease is a diagnosis of exclusion. **New rectal bleeding in age ≥50, or any alarm feature, still needs a colonoscopy plan** even when hemorrhoids are visible — the two can coexist with a cancer.\n\nReturn to the hub if another differential remains open.","citation":[8,17,19,20],"next":"arb-triage","recommendation":"Conservative care (fiber, softeners, sitz baths, topicals) + treat constipation; still arrange colonoscopy for age ≥50 or any alarm feature.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-benign-excluded' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-rescue (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Initial Bundle — Rectal Bleeding","body":"No emergent source ruled in; stable minor bleeding. Standard ED bundle while labs cook:\n\n- **IV access** (two large-bore if any volume concern), monitor, orthostatic vitals.\n- **Labs:** CBC (baseline + trend Hb), **type and screen** (cross if significant), coags/INR, BUN + creatinine (**BUN:Cr >30 hints upper source**), CMP, lactate if any instability; consider stool studies if diarrhea.\n- **Hold antithrombotics** pending assessment; correct coagulopathy if bleeding is significant.\n- **Rectal exam ± anoscopy** to document the source and exclude a mass.\n- **Fluids** for any orthostasis; transfuse to a **restrictive threshold (~7 g/dL)** if indicated.\n- **Risk-stratify** confirmed lower-GI bleeds with the **Oakland score** (toolbar): ≤10 identifies low-risk patients potentially suitable for outpatient management.\n\n**Reassess** for ongoing bleeding, Hb trend, and hemodynamic change.","citation":[3,9,11],"next":"arb-reassess","summary":"IV + CBC/type-and-screen/coags/BUN:Cr + hold antithrombotics + DRE/anoscopy + Oakland score. Reassess Hb + hemodynamics.","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-rescue' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-reassess (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Reassess — Bleeding + Hemodynamics","body":"Re-examine: is bleeding ongoing? Hb trend? Vitals / orthostatics? Oakland score? Source documented?","citation":[3,9,11],"options":[{"label":"Bleeding stopped + stable + low-risk (Oakland ≤10) + reliable","description":"Discharge pathway","next":"arb-disposition"},{"label":"Equivocal — needs endoscopy / imaging / observation","description":"Imaging / workup decision","next":"arb-imaging","urgency":"urgent"},{"label":"Ongoing bleeding / Hb dropping / hemodynamic change","description":"STOP — return to Rule In / Rule Out, resuscitate","next":"arb-triage","urgency":"critical"},{"label":"Specific source confirmed","description":"Leave the hub — work that deep-dive consult","next":"arb-disposition"}],"summary":"Stopped + stable + low-risk = discharge; equivocal = image/scope; ongoing/dropping Hb = STOP and resuscitate."}'::jsonb
WHERE id = 'arb-reassess' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-imaging (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Imaging / Workup Cheat-Sheet","body":"Match the study to the phenotype:\n\n**Colonoscopy** — the primary diagnostic + therapeutic tool for lower-GI bleeding; after resuscitation ± a rapid bowel purge. Also the mandatory follow-up study for new bleeding in age ≥50 or any alarm feature (malignancy exclusion).\n\n**CT angiography (CTA)** — for **brisk, ongoing** bleeding too unstable for prep or scope; localizes active extravasation (needs ~0.3-0.5 mL/min bleeding) and routes to **IR embolization**.\n\n**Upper endoscopy** — when an upper source is suspected (melena, hematemesis, BUN:Cr >30, hemodynamic instability out of proportion).\n\n**Tagged-RBC scintigraphy** — detects slower intermittent bleeding (~0.1 mL/min) when CTA is negative but bleeding continues.\n\n**Anoscopy / rigid proctoscopy** — bedside, to confirm a benign anorectal source and exclude a low rectal mass.\n\n**Do not send an unstable, actively bleeding patient to a prolonged prep** — resuscitate first, CTA/IR if too brisk for scope.","citation":[3,4,9],"next":"arb-disposition","summary":"Colonoscopy = primary tool; CTA/IR for brisk unstable bleeds; upper endoscopy if upper suspected; anoscopy for benign source. Never prep an unstable patient."}'::jsonb
WHERE id = 'arb-imaging' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-disposition (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Disposition","body":"Defer to the deep-dive consult’s admit criteria once a source is committed. The framework below applies to undifferentiated / benign-appearing bleeding.","citation":[3,9,11],"options":[{"label":"Admit — ongoing bleed, high-risk (Oakland >10), unstable, needs endoscopy/IR, significant comorbidity","description":"Admit per the deep-dive consult’s criteria","next":"arb-dispo-admit","urgency":"urgent"},{"label":"Observe — partial response, awaiting Hb trend / prep / endoscopy","description":"ED observation + serial Hb","next":"arb-dispo-observe"},{"label":"Discharge — self-limited, stable, low-risk (Oakland ≤10), reliable","description":"Standard discharge bundle","next":"arb-dispo-discharge"}],"summary":"Admit high-risk/ongoing/unstable; observe if equivocal; discharge low-risk self-limited with follow-up colonoscopy."}'::jsonb
WHERE id = 'arb-disposition' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-dispo-admit (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Admit","body":"Admit for: ongoing or recurrent hemorrhage, hemodynamic instability, a **high Oakland score (>10)**, significant anemia or a dropping Hb, need for urgent endoscopy or IR embolization, anticoagulation with a significant bleed, or major comorbidity.\n\n**Service:** GI / Medicine for most managed bleeds; **ICU** for hemodynamic instability, massive transfusion, or ongoing brisk bleeding; **Surgery / IR** for uncontrolled hemorrhage or a strangulated prolapse; **Colorectal surgery / Oncology** for an obstructing or bleeding malignancy.\n\n**Handoff:** onset + volume + character of bleeding, hemodynamic trend, Hb trend + transfusions given, coagulation status + any reversal given (drug + time), source (if localized), antithrombotic status, imaging/endoscopy performed + findings, comorbidities, allergies.","citation":[3,9,11],"recommendation":"Admit per deep-dive criteria; ICU for instability/massive transfusion; IR/surgery for uncontrolled bleed; standard handoff.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-dispo-admit' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-dispo-observe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Observe — Partial Response or Pending Workup","body":"ED observation when: bleeding has slowed but not clearly stopped, awaiting a repeat Hb, awaiting prep/endoscopy, or an intermediate Oakland score with social/safety barriers.\n\n**Protocol:** serial vitals + orthostatics; **repeat Hb at 4-6 h** (and sooner if any instability); watch for recurrent bleeding; continue fluids; keep antithrombotics held pending the plan.\n\n**Escalate** (admit / IR / endoscopy) for recurrent bleeding, a falling Hb, or hemodynamic change. **Discharge** with strict precautions and arranged follow-up if bleeding is clearly stopped, Hb is stable, and risk is low.","citation":[3,9,11],"recommendation":"Obs + serial vitals + repeat Hb at 4-6 h; escalate if recurrent bleed or falling Hb; discharge when stable + low-risk.","confidence":"recommended"}'::jsonb
WHERE id = 'arb-dispo-observe' AND tree_id = 'anorectal-bleeding-hub';

-- Node: arb-dispo-discharge (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Discharge — Universal Checklist","body":"Before discharge: (1) bleeding self-limited / clearly stopped, (2) vitals normal incl **no orthostasis**, (3) Hb stable / reassuring, (4) **low-risk Oakland score (≤10)** for a lower-GI bleed, (5) a **benign source documented** (or a clear plan to find one), (6) **reliable follow-up**, (7) **outpatient colonoscopy arranged** for new bleeding in age ≥50 or any alarm feature, (8) **written return precautions**.\n\n**Return precautions:** large-volume or recurrent bleeding, black/tarry stools, lightheadedness / fainting, chest pain / palpitations, weakness, abdominal pain, or a fever — return immediately.\n\n**Do NOT discharge if:** ongoing or high-volume bleeding, orthostasis, a dropping or significantly low Hb, a high Oakland score, an undocumented source in a high-risk patient, anticoagulation with a significant bleed, unreliable follow-up, or an alarm feature without a colonoscopy plan. Counsel: \"Bright-red blood is usually a benign source, but new bleeding after 50 — or with weight loss or anemia — needs a scope to be sure, even if we found hemorrhoids today.\"","citation":[3,9,11,19,20],"recommendation":"Discharge only if self-limited, no orthostasis, Hb stable, Oakland ≤10, source documented, colonoscopy arranged for age ≥50/alarm features, written precautions.","confidence":"definitive"}'::jsonb
WHERE id = 'arb-dispo-discharge' AND tree_id = 'anorectal-bleeding-hub';

-- Citations changed — DELETE and re-INSERT
DELETE FROM tree_citations WHERE tree_id = 'anorectal-bleeding-hub';
INSERT INTO tree_citations (tree_id, num, text) VALUES ('anorectal-bleeding-hub', 1, 'Sabry AO, Goosenberg E, Dsouza R, Sood T. Rectal Bleeding. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026. PMID: 33085290. NOTE: tertiary, non-peer-reviewed reference text — used here for background framing only. Every clinical recommendation in this consult is independently supported by the peer-reviewed society guidelines cited below.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('anorectal-bleeding-hub', 2, 'Wilkins T, Baird C, Pearson AN, Schade RR. Diverticular bleeding. Am Fam Physician. 2009;80(9):977-983. PMID: 19873964. NOTE: narrative review, retained for background epidemiology; management recommendations follow ref 3 and ref 9.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('anorectal-bleeding-hub', 3, 'Sengupta N, Feuerstein JD, Jairath V, Shergill AK, Strate LL, Wong RJ, Wan D. Management of Patients With Acute Lower Gastrointestinal Bleeding: An Updated ACG Guideline. Am J Gastroenterol. 2023;118(2):208-231. PMID: 36735555. doi:10.14309/ajg.0000000000002130');
