-- Node: fnb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Facial Peripheral Nerve Block — ED Procedure","body":"Regional anesthesia of the face anesthetizes a whole sensory territory from ONE distant injection — superior to local infiltration for facial wounds because it: (1) avoids tissue distortion of wound margins (critical for accurate cosmetic approximation, especially the vermilion border), (2) needs far less anesthetic volume, and (3) is less painful than multiple infiltrations.\n\nUse for laceration repair, abscess I&D, foreign-body removal, and burn care of the face.\n\nOpen first:\n- [Contraindications + pre-procedure checks](#/node/fnb-contra)\n- [Shared technique for all facial blocks](#/node/fnb-shared-technique)\n- [Procedure Steps Summary](#/info/fnb-steps)\n- [Stop / Pitfalls](#/info/fnb-stop)\n- Tools: [Max LA Dose](#/calculator/fnb-la-max-dose) calculator in the toolbar\n\nThen select which region you need to anesthetize.","citation":[1,15],"next":"fnb-region","summary":"Regional block of the face: no wound-margin distortion, less volume, less pain than infiltration.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-start' AND tree_id = 'facial-nerve-block';

-- Node: fnb-region (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Which Region Needs Anesthesia?","body":"Select the facial region of the wound or procedure. Each routes to the specific terminal trigeminal branch (or ear block) that covers it. Confirm the wound is suitable for delayed repair time (blocks add 5–10 min onset) and that there is no overlying infection at the planned injection site.","citation":[1,3],"options":[{"label":"Forehead / anterior scalp","description":"Supraorbital + supratrochlear nerve block (V1)","next":"fnb-supraorbital","urgency":"routine"},{"label":"Medial canthus / side of nose bridge","description":"Infratrochlear nerve block (V1)","next":"fnb-infratrochlear","urgency":"routine"},{"label":"Lower eyelid / cheek / upper lip / lateral nose","description":"Infraorbital nerve block (V2)","next":"fnb-infraorbital","urgency":"routine"},{"label":"Nasal tip / ala","description":"External nasal branch + infraorbital (V1/V2)","next":"fnb-nasal","urgency":"routine"},{"label":"Lower lip / chin","description":"Mental nerve block (V3)","next":"fnb-mental","urgency":"routine"},{"label":"Mandibular teeth / hemi-lower-lip","description":"Inferior alveolar nerve block (V3)","next":"fnb-inferior-alveolar","urgency":"routine"},{"label":"Temple / anterior ear region","description":"Auriculotemporal nerve block (V3)","next":"fnb-auriculotemporal","urgency":"routine"},{"label":"External ear (auricle)","description":"Ear ring block (auriculotemporal + great auricular)","next":"fnb-ear-ring","urgency":"routine"}],"summary":"Pick region → routes to supraorbital, infratrochlear, infraorbital, nasal, mental, inferior alveolar, auriculotemporal, or ear ring block."}'::jsonb
WHERE id = 'fnb-region' AND tree_id = 'facial-nerve-block';

-- Node: fnb-contra (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Contraindications + Pre-procedure Checks","body":"Absolute:\n- Overlying skin infection / cellulitis at the planned injection site (do not inject through infected tissue)\n- Known true allergy to the local anesthetic class (ester allergy more common than amide; if unsure, use a preservative-free amide or consult)\n- Patient refusal / inability to cooperate\n\nRelative — weigh risk/benefit:\n- Therapeutic anticoagulation (these are superficial blocks; bleeding risk is low — apply pressure, document)\n- Distorted anatomy from prior trauma/surgery at the foramen\n- Wound grossly contaminated and better served by infiltration after irrigation\n\nConfirm before any block:\n1. Informed consent (transient numbness, failed/partial block, vascular injection, hematoma, nerve irritation)\n2. Allergies (LA, latex, antiseptic)\n3. Anticoagulation status\n4. Calculate the [maximum safe LA dose](#/calculator/fnb-la-max-dose) BEFORE drawing up — facial blocks use small volumes (1–3 mL) so toxicity is rare, but verify when combining with wound infiltration.\n5. Aspirate before every injection — the face is highly vascular.","citation":[2,4],"next":"fnb-region","summary":"No infection at site, no LA allergy; verify max LA dose; aspirate before injecting (vascular face).","safetyLevel":"critical"}'::jsonb
WHERE id = 'fnb-contra' AND tree_id = 'facial-nerve-block';

-- Node: fnb-shared-technique (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Shared Technique — All Facial Blocks","body":"Equipment:\n- 3 mL syringe, 25–27 gauge needle (1–1.5 inch)\n- Antiseptic prep (chlorhexidine or alcohol)\n- 2x2 gauze, bandage\n\nAgent (choose one):\n- [Lidocaine 1–2%](#/drug/lidocaine/facial nerve block) — fast onset (2–5 min), 1–2 h duration\n- [Bupivacaine 0.25–0.5%](#/drug/bupivacaine/facial nerve block) — slower onset (5–10 min), 4–8 h duration; good for prolonged repairs\n- Epinephrine-containing LA is acceptable for most facial blocks and prolongs duration / reduces bleeding. AVOID epinephrine near end-arteries (nasal tip in compromised circulation) — though the classic \"no epi in the nose/ear\" dogma has been largely refuted, use judgment in vasculopaths.\n- Buffer lidocaine 9:1 with sodium bicarbonate to reduce injection pain.\n\nUniversal steps:\n1. Prep skin; let dry.\n2. Warn the patient of a brief sting.\n3. Insert needle, ADVANCE toward the target, ASPIRATE.\n4. Inject SLOWLY (slow injection = less pain). Never inject directly INTO a foramen (nerve injury) — deposit anesthetic adjacent to it.\n5. Wait 5–10 min and TEST the territory before starting the procedure.","citation":[2,5],"next":"fnb-region","summary":"25–27 ga, lidocaine (fast) or bupivacaine (long), aspirate, inject slowly NEXT TO not into the foramen, wait 5–10 min."}'::jsonb
WHERE id = 'fnb-shared-technique' AND tree_id = 'facial-nerve-block';

-- Node: fnb-supraorbital (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Supraorbital + Supratrochlear Block (V1)","body":"**Indication:** Lacerations/procedures of the forehead and anterior scalp to the vertex.\n\n**Distribution of anesthesia:** Ipsilateral forehead and anterior scalp (supraorbital covers the bulk; supratrochlear covers the medial forehead near the midline). Block both together for full hemi-forehead coverage.\n\n**Landmarks:**\n- The **supraorbital foramen/notch** sits on the superior orbital rim at the **mid-pupillary line** (palpable notch in many patients), roughly in vertical line with the pupil when looking straight ahead.\n- The **supratrochlear nerve** exits ~1–1.5 cm MEDIAL to the supraorbital foramen, near the superomedial orbital angle.\n\n**Technique:**\n1. Palpate the supraorbital notch at the mid-pupillary line on the brow ridge.\n2. Insert the needle just lateral to the notch and direct medially; raise a 1–2 mL wheal over the foramen (do not enter it). Aspirate first.\n3. Without withdrawing fully, redirect medially along the orbital rim toward the superomedial angle and inject another 1 mL to capture the supratrochlear nerve.\n4. Total ~2–3 mL. Apply pressure to limit eyelid ecchymosis.\n\nPitfall: injecting too inferiorly causes upper-eyelid swelling — stay on the rim.","citation":[6,12],"next":"fnb-test","summary":"Forehead/anterior scalp. Supraorbital foramen at mid-pupillary line on brow ridge; supratrochlear 1 cm medial. ~2–3 mL."}'::jsonb
WHERE id = 'fnb-supraorbital' AND tree_id = 'facial-nerve-block';

-- Node: fnb-infratrochlear (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Infratrochlear Block (V1)","body":"**Indication:** Lacerations of the medial canthal region, the bridge/upper-lateral side of the nose, and the medial lower eyelid.\n\n**Distribution of anesthesia:** Skin of the medial canthus, root and bridge of the nose, medial upper eyelid, and lacrimal sac region.\n\n**Landmarks:**\n- The **infratrochlear nerve** exits below the trochlea at the **superomedial corner of the orbit**, at the junction of the orbital roof and medial wall (just above the medial canthal tendon / medial canthus).\n\n**Technique:**\n1. Identify the medial canthus and the superomedial orbital angle.\n2. Insert at the superomedial orbital rim, just above the medial canthus, directing toward the bony angle. Aspirate.\n3. Inject 1–2 mL adjacent to the bone. Keep the needle superficial and aim AWAY from the globe.\n\nPitfall: medial orbital structures and the angular vessels — aspirate, inject slowly, and apply pressure to avoid hematoma.","citation":[7,12],"next":"fnb-test","summary":"Medial canthus / nose bridge. Exits at superomedial orbital angle just above medial canthus. 1–2 mL, aim away from globe."}'::jsonb
WHERE id = 'fnb-infratrochlear' AND tree_id = 'facial-nerve-block';

-- Node: fnb-infraorbital (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Infraorbital Block (V2)","body":"**Indication:** The workhorse facial block — lacerations of the lower eyelid, medial cheek, lateral side of the nose, and the UPPER LIP (preserves the vermilion border without distortion).\n\n**Distribution of anesthesia:** Ipsilateral lower eyelid, medial cheek, lateral nose, and upper lip (and via anterior superior alveolar branches, the maxillary incisors/canine).\n\n**Landmarks:**\n- The **infraorbital foramen** lies ~**1 cm below the infraorbital rim**, in the **mid-pupillary line** — vertically aligned with the supraorbital notch and the mental foramen.\n\n**Two approaches:**\n- **Intraoral (preferred — less painful, smaller scar risk):**\n  1. Palpate the foramen externally and keep a fingertip over it.\n  2. Retract the upper lip; insert the needle in the gingivobuccal sulcus above the 2nd premolar / canine, parallel to the long axis of the tooth.\n  3. Advance ~1.5–2 cm toward the palpating finger over the foramen. Aspirate.\n  4. Inject 2–3 mL adjacent to (NOT into) the foramen. The palpating finger prevents superior spread toward the orbit.\n- **Extraoral (percutaneous):** insert ~1 cm below the rim at the mid-pupillary line, direct toward the foramen, aspirate, inject 2–3 mL beside it.\n\nPitfall: never force the needle into the foramen — paresthesia/nerve injury. Keep the finger over the foramen during intraoral approach to direct flow and protect the eye.","citation":[8,15],"next":"fnb-test","summary":"Lower eyelid/cheek/upper lip/lateral nose. Foramen 1 cm below infraorbital rim at mid-pupillary line. Intraoral via gingivobuccal sulcus, finger over foramen, 2–3 mL."}'::jsonb
WHERE id = 'fnb-infraorbital' AND tree_id = 'facial-nerve-block';

-- Node: fnb-nasal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"External Nasal / Nasal Tip Block (V1 + V2)","body":"**Indication:** Lacerations of the nasal tip, ala, and columella.\n\n**Distribution of anesthesia:** The nasal tip and dorsum are supplied by the **external nasal branch of the anterior ethmoidal nerve (V1)**; the ala and lateral nose by the **infraorbital nerve (V2)**. Full tip anesthesia often needs BOTH.\n\n**Landmarks:**\n- The **external nasal branch** emerges at the junction of the **nasal bone and the upper lateral cartilage** (where the bony dorsum meets the cartilaginous dorsum), in the midline-to-paramedian dorsum.\n\n**Technique:**\n1. For the dorsum/tip: raise a small wheal (0.5–1 mL) at the bony-cartilaginous junction of the nasal dorsum on each side, where the external nasal branch emerges.\n2. For the ala/lateral nose: add a bilateral [infraorbital block](#/node/fnb-infraorbital) as above.\n3. Use small volumes (highly vascular, end-arterial tip). Aspirate. Apply gentle pressure.\n\nPitfall: the nasal tip has limited collateral flow — keep volumes small; the old \"never use epinephrine on the nose\" rule is no longer absolute, but be conservative in vasculopaths.","citation":[9,15],"next":"fnb-test","summary":"Nasal tip/ala. External nasal branch at nasal bone–cartilage junction (0.5–1 mL each side) ± bilateral infraorbital. Small volumes."}'::jsonb
WHERE id = 'fnb-nasal' AND tree_id = 'facial-nerve-block';

-- Node: fnb-mental (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Mental Nerve Block (V3)","body":"**Indication:** Lacerations/procedures of the LOWER LIP and chin (preserves the vermilion border).\n\n**Distribution of anesthesia:** Ipsilateral lower lip and chin skin/mucosa (terminal branch of the inferior alveolar nerve).\n\n**Landmarks:**\n- The **mental foramen** lies below the **2nd mandibular premolar (apex)**, roughly midway between the upper and lower borders of the mandible, in the **mid-pupillary line** (vertically aligned with the supraorbital and infraorbital foramina). In edentulous patients it migrates superiorly toward the alveolar ridge.\n\n**Two approaches:**\n- **Intraoral (preferred):**\n  1. Retract the lower lip; identify the gingivobuccal sulcus at the 2nd premolar.\n  2. Insert the needle into the sulcus aiming toward the foramen; advance ~1 cm. Aspirate.\n  3. Inject 1–2 mL adjacent to the foramen.\n- **Extraoral:** palpate the foramen below the 2nd premolar; inject 1–2 mL percutaneously beside it.\n\nPitfall: do not enter the foramen (nerve injury). Bilateral blocks needed for midline lower-lip wounds crossing midline.","citation":[10,15],"next":"fnb-test","summary":"Lower lip/chin. Mental foramen below 2nd premolar at mid-pupillary line. Intraoral via sulcus, 1–2 mL beside foramen. Bilateral for midline."}'::jsonb
WHERE id = 'fnb-mental' AND tree_id = 'facial-nerve-block';

-- Node: fnb-inferior-alveolar (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Inferior Alveolar Nerve Block (V3)","body":"**Indication:** Mandibular dental pain/procedures, and extensive lower-lip/chin wounds where a more proximal block than the mental nerve is needed (anesthetizes the entire hemi-mandible and ipsilateral lower lip).\n\n**Distribution of anesthesia:** All ipsilateral mandibular teeth, the body of the mandible, the ipsilateral lower lip and chin (via the mental branch), and the anterior 2/3 of the tongue + floor of mouth on that side (lingual nerve co-block is common).\n\n**Landmarks:**\n- Target the **mandibular foramen** on the medial ramus. The needle entry is at the **coronoid notch / pterygomandibular raphe**, ~1 cm above the mandibular occlusal plane.\n\n**Technique (intraoral):**\n1. Palpate the coronoid notch (deepest concavity on the anterior ramus) with the thumb; rest fingers on the posterior ramus to stabilize.\n2. Approach from the contralateral premolars; insert the needle lateral to the pterygomandibular raphe at the level ~1 cm above the lower molar occlusal surface.\n3. Advance ~2–2.5 cm until you gently contact bone (medial ramus), then withdraw 1 mm. Aspirate (the inferior alveolar artery/vein run with the nerve).\n4. Inject 1.5–2 mL. Onset 3–5 min; expect lower-lip numbness as the sign of success.\n\nPitfall: highly vascular — aspirate carefully; positive aspiration → withdraw/redirect. This is a deeper, more technical block; if unfamiliar, a mental block usually suffices for skin wounds.","citation":[11,15],"next":"fnb-test","summary":"Hemi-mandible/teeth + lower lip. Mandibular foramen via coronoid notch, contact bone, withdraw 1mm, aspirate, 1.5–2 mL. Vascular.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-inferior-alveolar' AND tree_id = 'facial-nerve-block';

-- Node: fnb-auriculotemporal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Auriculotemporal Nerve Block (V3)","body":"**Indication:** Lacerations/procedures of the temple, the tragus and anterior/superior auricle, and the skin anterior to the ear.\n\n**Distribution of anesthesia:** Temple skin, anterior/superior external ear (tragus, anterior helix), anterior external auditory canal, and the TMJ region.\n\n**Landmarks:**\n- The **auriculotemporal nerve** runs with the **superficial temporal artery** just ANTERIOR to the tragus/ear, crossing the zygomatic root. Palpate the superficial temporal pulse anterior to the tragus.\n\n**Technique:**\n1. Palpate the superficial temporal artery anterior to the tragus.\n2. Insert just anterior and superior to the tragus, posterior to the palpated artery. Aspirate (artery is right there).\n3. Inject 2–3 mL of LA in a subcutaneous fan anterior to the ear at the level of the zygomatic root.\n\nPitfall: the superficial temporal artery is immediately adjacent — ALWAYS aspirate; intravascular injection risk is real here.","citation":[12,15],"next":"fnb-test","summary":"Temple / anterior ear. Auriculotemporal nerve runs with superficial temporal artery anterior to tragus. Aspirate (artery!), 2–3 mL fan.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-auriculotemporal' AND tree_id = 'facial-nerve-block';

-- Node: fnb-ear-ring (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"External Ear Ring Block","body":"**Indication:** Lacerations, hematoma I&D (auricular hematoma/cauliflower ear), and procedures of the external ear (auricle) — anesthetizes the whole auricle except the concha/EAC.\n\n**Distribution of anesthesia:** The auricle receives a quadruple supply: **great auricular nerve** (most of the posterior/inferior auricle), **auriculotemporal nerve** (anterior/superior auricle), **lesser occipital** (small superoposterior area), and the **auricular branch of the vagus (Arnold)** (concha + EAC — NOT covered by a ring block; supplement with local infiltration of the concha if needed).\n\n**Landmarks / technique (subcutaneous ring around the ear):**\n1. Insert at the **superior** ear attachment; direct the needle inferiorly along the ANTERIOR (anterior to tragus) sulcus and inject ~1.5–2 mL as you withdraw.\n2. Redirect from the same superior entry posteriorly along the POSTERIOR auricular sulcus; inject ~1.5–2 mL.\n3. Repeat from the **inferior** ear attachment (lobule), injecting anteriorly and posteriorly, creating a complete diamond/ring of anesthetic around the ear base.\n4. Aspirate at each pass. Total ~6–8 mL — verify against the [max LA dose](#/calculator/fnb-la-max-dose).\n5. The concha and external canal (Arnold/vagal supply) need separate local infiltration.\n\nPitfall: classic teaching avoided epinephrine in the ear; current evidence shows epinephrine is generally safe, but stay conservative in vasculopaths and avoid encircling pressure that could compromise the auricle.","citation":[13,16],"next":"fnb-test","summary":"Whole auricle (not concha/canal). Subcutaneous ring from superior + inferior entries, anterior + posterior passes, ~6–8 mL, aspirate. Concha = Arnold/vagus, infiltrate separately."}'::jsonb
WHERE id = 'fnb-ear-ring' AND tree_id = 'facial-nerve-block';

-- Node: fnb-test (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Test the Block Before Proceeding","body":"Wait 5–10 minutes, then test pinprick/sharp sensation across the intended territory and compare to the contralateral side.\n\nIs the territory anesthetized?","citation":[1,6],"options":[{"label":"Yes — fully numb","description":"Proceed with the wound repair or procedure","next":"fnb-complications","urgency":"routine"},{"label":"Partial / patchy","description":"Supplement: re-block (verify landmark) or add small-volume local infiltration at the deficient edge (stay under max LA dose)","next":"fnb-partial","urgency":"routine"},{"label":"No effect after 10 min","description":"Recheck landmark and foramen position; consider anatomic variation; re-attempt once or switch to local infiltration","next":"fnb-partial","urgency":"routine"}],"summary":"Wait 5–10 min, test pinprick vs contralateral. Full → proceed. Partial/none → supplement or re-block within max dose."}'::jsonb
WHERE id = 'fnb-test' AND tree_id = 'facial-nerve-block';

-- Node: fnb-partial (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Rescue a Partial / Failed Block","body":"Causes of failure:\n- Wrong foramen level (recheck the mid-pupillary line alignment for supraorbital/infraorbital/mental)\n- Anatomic variation in foramen position\n- Insufficient wait time (bupivacaine can take 8–10 min)\n- Too little volume\n\nRescue options:\n1. Re-confirm the landmark and re-inject 1–2 mL adjacent to the foramen (aspirate first).\n2. Add targeted LOCAL infiltration at the still-sensate wound edge — small volume, injected slowly, from within the wound margin to minimize pain.\n3. ALWAYS re-check the running total against the [max LA dose](#/calculator/fnb-la-max-dose) before adding more anesthetic.\n4. If still failing, proceed with full local infiltration or reassess the plan.","citation":[2,6],"next":"fnb-complications","summary":"Failure = wrong level / variation / short wait / low volume. Re-block, add local infiltration, recheck max dose."}'::jsonb
WHERE id = 'fnb-partial' AND tree_id = 'facial-nerve-block';

-- Node: fnb-complications (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Complications + Recognition","body":"Common / minor:\n- Local hematoma or ecchymosis (especially periorbital blocks and auriculotemporal near the temporal artery) — apply pressure\n- Transient pain on injection\n- Failed/partial block\n- Prolonged numbness beyond expected duration (self-limited)\n\nUncommon but important:\n- **Intravascular injection** — facial vasculature is dense (angular, infraorbital, superficial temporal, inferior alveolar vessels). Aspirate before EVERY injection. Systemic LA toxicity (perioral numbness, tinnitus, metallic taste → seizures, cardiac) is the feared endpoint — keep total dose under the calculated maximum.\n- **Nerve injury / persistent paresthesia** — from injecting INTO a foramen or intraneural injection. Prevent by depositing anesthetic ADJACENT to, never inside, the foramen, and stopping if the patient reports an electric shock.\n- **Globe injury** — only a risk with periorbital (supraorbital/infratrochlear) blocks; keep the needle on the orbital rim and direct away from the globe.\n- **Infection** — rare with antiseptic prep; never inject through infected skin.\n\n**Local anesthetic systemic toxicity (LAST):** if suspected → stop injecting, give O2, manage airway, treat seizures (benzodiazepine), and give 20% **lipid emulsion** 1.5 mL/kg bolus then infusion. Have it available for high-volume blocks.","citation":[4,14],"next":"fnb-doc","summary":"Hematoma, intravascular injection (aspirate!), nerve injury (inject beside not into foramen), globe risk (periorbital), LAST → lipid emulsion.","safetyLevel":"warning"}'::jsonb
WHERE id = 'fnb-complications' AND tree_id = 'facial-nerve-block';

-- Node: fnb-doc (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Procedure Note Template","body":"**Procedure:** [Supraorbital+supratrochlear / Infratrochlear / Infraorbital / External nasal / Mental / Inferior alveolar / Auriculotemporal / Ear ring] nerve block, [right/left/bilateral].\n**Indication:** [Facial laceration repair / abscess I&D / foreign-body removal / burn care] at [site].\n**Consent:** Verbal informed consent obtained; risks of transient numbness, failed/partial block, hematoma, intravascular injection, and nerve irritation discussed; patient agrees.\n**Allergies / anticoagulation:** [documented].\n**Agent / dose:** [Lidocaine 1% / Bupivacaine 0.25–0.5%] [± epinephrine], [X] mL total — confirmed under maximum weight-based dose ([X] mg/kg).\n**Landmarks:** [foramen at mid-pupillary line / coronoid notch / superficial temporal pulse / ear ring], identified by palpation.\n**Technique:** [intraoral / extraoral / ring]; 25–27 ga needle; negative aspiration before each injection; slow injection adjacent to (not into) the foramen.\n**Effect:** Adequate anesthesia confirmed by pinprick at [X] min; procedure performed.\n**Tolerance / complications:** Tolerated well; no hematoma, intravascular injection, or LAST.\n**Disposition:** [wound aftercare + return precautions given].","citation":[1,3],"recommendation":"Document block type, indication, consent, agent/dose (under max), landmarks, aspiration, confirmed effect, and disposition.","confidence":"definitive","summary":"Note must capture: block type, indication, consent, agent/dose under max, landmarks, aspiration, confirmed effect, dispo."}'::jsonb
WHERE id = 'fnb-doc' AND tree_id = 'facial-nerve-block';

