-- Node: onb-indication (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Why Are You Blocking?","body":"Confirm a benign headache phenotype has been worked up. Secondary causes (SAH, dissection, CVST, AACG, hypertensive emergency, meningitis) MUST be excluded first.","citation":[1,2,3,5],"options":[{"label":"Cluster headache — acute attack","description":"Severe unilateral periorbital/temporal pain with autonomic features; failed O2 + SQ triptan or contraindication","next":"onb-contra","urgency":"urgent"},{"label":"Cluster headache — bridge therapy","description":"Active cluster bout; transitioning to verapamil prophylaxis; oral steroid contraindicated","next":"onb-contra","urgency":"urgent"},{"label":"Occipital neuralgia","description":"Paroxysmal sharp shooting pain in GON distribution; tender over GON; reproducible on palpation","next":"onb-contra","urgency":"routine"},{"label":"Cervicogenic / post-traumatic HA","description":"Unilateral headache with cervical movement triggers, or persistent post-traumatic occipital pain","next":"onb-contra","urgency":"routine"},{"label":"Status migrainosus — refractory","description":"Migraine >72 h refractory to IV cocktail (Metoclopramide + Diphenhydramine + Ketorolac + Dexamethasone + IVF) and DHE","next":"onb-contra","urgency":"urgent"},{"label":"Diagnosis unclear — return to hub","description":"Send back through the Headache Hub red-flag screener first","next":"onb-no-indication"}],"summary":"Cluster (acute + bridge), occipital neuralgia, cervicogenic, post-traumatic, refractory status migrainosus."}'::jsonb
WHERE id = 'onb-indication' AND tree_id = 'occipital-nerve-block';

-- Node: onb-no-indication (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":1,"title":"Return to Headache Hub for Workup","body":"No clear indication for occipital block. Re-screen for red flags + complete diagnostic workup before considering a procedural option.\n\nOpen [Headache Hub](#/tree/headache-hub).","citation":[1,3],"recommendation":"Do not perform ONB without a defined indication.","confidence":"definitive","safetyLevel":"warning"}'::jsonb
WHERE id = 'onb-no-indication' AND tree_id = 'occipital-nerve-block';

-- Node: onb-contra (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Contraindications + Pre-procedure Checks","body":"Absolute:\n- Overlying skin infection at injection site\n- Known allergy to local anesthetic class (amide LA cross-reactivity is rare; ester allergy is more common)\n- Patient refusal\n\nRelative — escalate / consult:\n- Therapeutic anticoagulation (INR >3, new DOAC dose <24 h, unfractionated heparin gtt) — per ASRA 2018 deep peripheral block guidance, ONB is superficial and bleeding risk is low, but document risk/benefit\n- Prior skull defect / craniectomy at injection site (palpate carefully, ultrasound if available)\n- Active occipital scalp pathology (alopecia areata in injection field, cellulitis, prior infection)\n- Pregnancy: LA is generally safe; AVOID steroid adjunct (use LA-only)\n\nConfirm:\n1. Informed verbal/written consent (vasovagal, transient numbness, alopecia at site if steroid used, intra-arterial injection risk)\n2. Allergies (LA, latex, antiseptic)\n3. Anticoagulation status + last dose\n4. IV access if vasovagal-prone or anxious patient\n5. Monitor in place for 15 min post-procedure","citation":[2,4,14,15],"next":"onb-anatomy-ref","summary":"No skin infection, no LA allergy, document anticoag risk/benefit; no steroid in pregnancy.","safetyLevel":"critical"}'::jsonb
WHERE id = 'onb-contra' AND tree_id = 'occipital-nerve-block';

-- Node: onb-setup (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Setup — Patient + Equipment","body":"Patient position:\n- Seated with head flexed forward, forehead resting on a pillow (preferred), OR\n- Prone if cluster patient cannot tolerate sitting up\n\nEquipment:\n- 3 mL syringe\n- 25-27 gauge needle (1-1.5 inch / 25-38 mm)\n- Chlorhexidine or alcohol prep\n- Sterile gloves (clean technique acceptable; full sterile is overkill for a superficial peripheral block)\n- 2x2 gauze for hemostasis\n- Adhesive bandage\n\nMedications — choose one:\n- [Bupivacaine 0.5%](#/drug/bupivacaine/occipital nerve block) 2-3 mL PLAIN (no epinephrine — risk of vasoconstriction near vertebral system)\n- [Lidocaine 1-2%](#/drug/lidocaine/occipital nerve block) 2-3 mL PLAIN if bupivacaine unavailable or shorter duration desired\n\nOptional steroid adjunct — case-dependent:\n- [Methylprednisolone depot](#/drug/methylprednisolone/occipital nerve block) 40 mg mixed with LA, OR\n- [Dexamethasone](#/drug/dexamethasone/occipital nerve block) 4 mg mixed with LA\n\nEvidence note: RCTs (Ashkenazi 2008, Cuadrado 2017) show steroid does NOT add benefit beyond LA-alone for cluster. Steroid adjunct is reasonable for cervicogenic headache and hemicrania continua only. Avoid steroid in pregnancy and in repeated blocks (alopecia, Cushingoid features).","citation":[2,8,9,10],"next":"onb-mark","summary":"Seated head-down or prone; 25-27 ga needle; bupivacaine 0.5% PLAIN 2-3 mL; steroid only for cervicogenic."}'::jsonb
WHERE id = 'onb-setup' AND tree_id = 'occipital-nerve-block';

-- Node: onb-inject (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Step 2 — Inject","body":"1. Hold the syringe perpendicular to the skull.\n2. Advance the needle slowly until you contact bone (skull is the safety stop — prevents intracranial penetration).\n3. Withdraw 1-2 mm off bone.\n4. **ASPIRATE** before injecting. If blood returns → withdraw, redirect 1-2 mm medially, re-aspirate. Intra-arterial injection into the occipital artery (which feeds into the vertebral system via collaterals) can cause seizure or transient neurologic symptoms.\n5. Inject 2-3 mL of LA (± steroid adjunct) in a slow, steady manner over ~30 seconds. Patient may report referred pressure or transient sharp pain — normal.\n6. Withdraw needle, apply pressure with gauze for 1-2 min, place bandage.\n7. Repeat on contralateral side ONLY if bilateral indication (cluster is unilateral — only block the symptomatic side; bilateral block for migraine variants is acceptable per AHS).\n\n**Maximum safe LA dose:** Bupivacaine plain ~2 mg/kg (e.g., 14 mg for 70 kg = ~3 mL of 0.5%); Lidocaine plain ~4.5 mg/kg.","citation":[8,9,16],"next":"onb-aspirate-positive","summary":"Contact bone, withdraw 1-2 mm, ASPIRATE, inject 2-3 mL slowly.","safetyLevel":"critical"}'::jsonb
WHERE id = 'onb-inject' AND tree_id = 'occipital-nerve-block';

-- Node: onb-aspirate-positive (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Aspirate Returned Blood — What Now?","body":"You aspirated before injecting (good) and got blood return. The occipital artery runs near the GON target. Do NOT inject at this position.","citation":[8,15],"options":[{"label":"Withdraw and redirect medially 1-2 mm","description":"GON lies medial to the artery. Re-aspirate. Inject only if dry.","next":"onb-post-procedure","urgency":"urgent"},{"label":"Abort the procedure","description":"If unable to redirect to a dry pocket after 2 attempts, do not proceed. Discuss alternative (sphenopalatine block, pharmacologic) with patient.","next":"onb-post-procedure"}],"safetyLevel":"critical"}'::jsonb
WHERE id = 'onb-aspirate-positive' AND tree_id = 'occipital-nerve-block';

-- Node: onb-complications (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Complications + Recognition","body":"Common (1-5%):\n- Vasovagal syncope — preventable with supine positioning post-procedure + 15 min observation\n- Local soreness 1-2 days\n- Transient occipital numbness extending beyond intended duration\n\nUncommon but serious:\n- **Intra-arterial injection (occipital artery → vertebral collateral)** — can cause seizure, transient neurologic deficit, or stroke. PREVENT by aspirating before every injection.\n- Infection at injection site (rare with clean technique; treat as cellulitis if it occurs)\n- Persistent neuropathic pain or paresthesia in GON distribution (rare; usually self-limited)\n- Alopecia at injection site (with steroid use; usually patchy and reversible)\n- Cushingoid features with repeated steroid blocks (limit to ≤4 per year)\n- Allergic reaction (rare; amide LA cross-reactivity is uncommon)\n\n**Action if complication suspected:**\n- Seizure / neuro deficit → immediate stroke workup ([SAH](#/tree/sah) / [ICH](#/tree/ich) protocol depending on findings)\n- Infection → standard cellulitis workup + treatment\n- Expanding hematoma → direct pressure, observation, ultrasound if concerning","citation":[11,12,15],"next":"onb-doc","summary":"Vasovagal 1-3%, intra-arterial → seizure/deficit, alopecia/Cushingoid with steroid.","safetyLevel":"warning"}'::jsonb
WHERE id = 'onb-complications' AND tree_id = 'occipital-nerve-block';

-- Node: onb-doc (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Procedure Note Template","body":"**Procedure:** Greater occipital nerve block, [right/left/bilateral]\n**Indication:** [Cluster headache acute attack / Cluster bridge / Occipital neuralgia / Cervicogenic HA / Post-traumatic HA / Status migrainosus refractory]\n**Consent:** Verbal informed consent obtained; risks of vasovagal, transient numbness, intra-arterial injection, infection, alopecia (if steroid) discussed; patient agrees to proceed.\n**Landmarks:** Inion and mastoid palpated; injection point marked 1/3 distance from inion to mastoid along superior nuchal line; occipital artery pulse identified and avoided (injection 1-2 cm medial).\n**Prep:** Chlorhexidine prep × 1; sterile technique.\n**Agent:** [Bupivacaine 0.5% 2-3 mL plain / Lidocaine 1-2% 2-3 mL plain] [± Methylprednisolone 40 mg / Dexamethasone 4 mg].\n**Technique:** 25-gauge needle advanced perpendicular to bone, withdrawn 1-2 mm, negative aspiration, slow injection over 30 sec.\n**Tolerance:** Patient tolerated well; no complications.\n**Post-procedure:** Onset of numbness at [X] min; pain relief at [X] min (cluster); observed 15 min; no vasovagal symptoms; discharged with return precautions and [follow-up plan].","citation":[12,13],"recommendation":"Document indication, landmarks, agent, aspiration, response, and disposition.","confidence":"definitive","summary":"Procedure note must capture: indication, consent, landmarks, agent, aspiration, response, observation, dispo."}'::jsonb
WHERE id = 'onb-doc' AND tree_id = 'occipital-nerve-block';

