-- Node: tsi-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Tendon-Sheath Steroid Injection — de Quervain / Trigger Finger","body":"A single corticosteroid injection into the tendon sheath is first-line for de Quervain tenosynovitis and trigger finger, often giving same-visit relief.\n\nTools (open first):\n- [Procedure Steps Summary](#/info/tsi-steps)\n- [Steroid Prep + Dose Card](#/info/tsi-steroid-dose)\n- [Sheath-vs-Tendon Confirmation Checklist](#/info/tsi-sheath-confirm)\n- [Skin Atrophy / Depigmentation Caution](#/info/tsi-atrophy)\n- [Hand-Surgery Referral Criteria](#/info/tsi-referral)","citation":[1,2,6,9],"next":"tsi-diagnose","summary":"Single steroid injection is first-line for de Quervain + trigger finger; confirm sheath, avoid SC deposit.","safetyLevel":"warning"}'::jsonb
WHERE id = 'tsi-start' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-diagnose (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Which Condition?","body":"Confirm the diagnosis clinically and exclude infection before injecting any steroid.","citation":[1,2,3,5],"options":[{"label":"de Quervain tenosynovitis","description":"Radial-sided wrist pain over the first dorsal compartment; positive Finkelstein (pain with thumb-in-fist ulnar deviation); tender/swollen over the radial styloid.","next":"tsi-contra","urgency":"routine"},{"label":"Trigger finger (stenosing tenosynovitis, A1 pulley)","description":"Catching/locking of a finger in flexion; palpable tender nodule at the A1 pulley over the distal palm/MCP; painful triggering with flexion-extension.","next":"tsi-contra","urgency":"routine"},{"label":"Uncertain / red flags","description":"Signs of infection (flexor tenosynovitis — Kanavel signs), trauma, or atypical features. Do NOT inject; work up first.","next":"tsi-redflag","urgency":"urgent"}],"summary":"de Quervain (Finkelstein) vs trigger finger (A1 nodule/triggering); exclude infection."}'::jsonb
WHERE id = 'tsi-diagnose' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-contra (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Contraindications + Consent","body":"Before injecting:\n- **Absolute:** overlying skin infection, suspected septic tenosynovitis, known steroid/anesthetic allergy\n- **Relative / counsel:** poorly controlled diabetes (transient glucose rise), prior injections at the same site (limit repeats; diminishing returns and tissue effects), anticoagulation (superficial injection, low risk; hold pressure)\n- **Consent points:** transient post-injection flare, fat atrophy and skin depigmentation at the site (more visible in darker skin — see [Skin Atrophy / Depigmentation Caution](#/info/tsi-atrophy)), tendon rupture if injected into the tendon itself, infection, and that symptoms may recur and need surgery","citation":[3,4,7],"next":"tsi-select","summary":"No infection/septic sheath/allergy; counsel flare, fat atrophy/depigmentation, rupture, recurrence.","safetyLevel":"warning"}'::jsonb
WHERE id = 'tsi-contra' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-select (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Proceed to Target","body":"Pick the compartment to inject. Each uses the same principle: deposit steroid + anesthetic INTO the sheath (free flow, low resistance), not into the tendon.","citation":[4,8],"options":[{"label":"First dorsal compartment (de Quervain)","description":"Inject the sheath of APL/EPB at the radial styloid.","next":"tsi-dq-landmark","urgency":"routine"},{"label":"A1 pulley (trigger finger)","description":"Inject the flexor sheath at the A1 pulley over the distal palm.","next":"tsi-tf-landmark","urgency":"routine"}],"summary":"Choose first dorsal compartment (de Quervain) or A1 pulley (trigger finger)."}'::jsonb
WHERE id = 'tsi-select' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-dq-landmark (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"de Quervain — Landmarks","body":"Target: the first dorsal compartment sheath containing **abductor pollicis longus (APL)** and **extensor pollicis brevis (EPB)** at the radial styloid.\n\n1. Identify the radial styloid; palpate the tender APL/EPB tendons as the patient extends/abducts the thumb.\n2. Beware the **radial sensory nerve** branches and the radial artery in the anatomical snuffbox just distal/dorsal — avoid them.\n3. Watch for a septum dividing EPB into its own subcompartment (present in a substantial minority) — a cause of injection failure; ultrasound guidance improves accuracy if available.\n\n**[IMAGE PENDING ANDY APPROVAL]** — a first-dorsal-compartment landmark diagram is planned here pending approval per project image rule.","citation":[5,9,10],"next":"tsi-technique","summary":"First dorsal compartment (APL/EPB) at radial styloid; avoid radial sensory nerve/artery; watch for septum."}'::jsonb
WHERE id = 'tsi-dq-landmark' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-tf-landmark (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Trigger Finger — Landmarks","body":"Target: the **flexor tendon sheath at the A1 pulley**, located over the metacarpal head / distal palmar crease region of the affected digit (palpable tender nodule that moves with the tendon).\n\n1. Palpate the A1 pulley nodule at the distal palm over the MCP of the affected finger.\n2. Approach from the palmar surface at a shallow angle aimed proximally/into the sheath; the digital neurovascular bundles run along the sides of the finger — stay midline over the tendon.\n\n**[IMAGE PENDING ANDY APPROVAL]** — an A1-pulley landmark diagram is planned here pending approval per project image rule.","citation":[2,11],"next":"tsi-technique","summary":"A1 pulley at distal palm over MCP nodule; palmar midline approach; avoid lateral digital bundles."}'::jsonb
WHERE id = 'tsi-tf-landmark' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-technique (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Injection Technique","body":"Same principle for both targets. Dose details in [Steroid Prep + Dose Card](#/info/tsi-steroid-dose).\n\n1. Sterile prep. Draw corticosteroid + a small volume of [Lidocaine 1%](#/drug/lidocaine/tendon sheath injection) (e.g., ~1 mL total injectate).\n2. Insert a 25-27 ga needle into the sheath at the landmark.\n3. **Confirm you are in the sheath, not the tendon** — use the [Sheath-vs-Tendon Confirmation Checklist](#/info/tsi-sheath-confirm): the injectate should flow with LOW resistance; if you meet high resistance, you are likely in the tendon — withdraw slightly. A classic confirmation is watching the needle move with passive tendon excursion (in-tendon) vs staying still (in-sheath); back the needle out until it no longer moves with the tendon.\n4. Inject slowly. Stop and reposition if resistance is high.\n5. Keep the deposit deep in the sheath, NOT subcutaneous (subcutaneous steroid causes fat atrophy/depigmentation).","citation":[1,4,8,11],"next":"tsi-resistance","summary":"Steroid + lidocaine into sheath; low-resistance flow; back out if needle moves with tendon; avoid SC.","safetyLevel":"critical"}'::jsonb
WHERE id = 'tsi-technique' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-resistance (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"High Resistance on Injection?","body":"Resistance is the key intra-procedural safety signal. **High resistance = needle in the tendon — injecting risks rupture.**","citation":[4,8,11],"options":[{"label":"Low resistance, free flow","description":"You are in the sheath. Complete the injection slowly.","next":"tsi-aftercare","urgency":"routine"},{"label":"High resistance / needle moves with tendon","description":"Stop. Withdraw the needle 1-2 mm until flow is free and the needle no longer moves with passive tendon motion, then inject.","next":"tsi-aftercare","urgency":"urgent"}],"summary":"Low resistance → inject; high resistance → withdraw off the tendon before injecting.","safetyLevel":"critical"}'::jsonb
WHERE id = 'tsi-resistance' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-aftercare (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Aftercare + Counseling","body":"1. Apply a small dressing; brief pressure.\n2. Counsel:\n- Relief typically over days; up to ~70% improve after a single injection for trigger finger; de Quervain also responds well, especially with a complete sheath block.\n- A transient post-injection pain flare in the first 24-48 h is common.\n- Watch the injection site for fat atrophy / skin depigmentation (usually months later, often reversible).\n- Return for signs of infection (spreading redness, warmth, fever) or for tendon-rupture symptoms (sudden loss of motion).\n3. Activity: relative rest; a thumb spica (de Quervain) or brief splinting can be adjunctive.\n4. Repeat injections have diminishing returns — persistent/recurrent cases go to hand surgery (see [Hand-Surgery Referral Criteria](#/info/tsi-referral)).","citation":[6,7,9,12],"next":"tsi-doc","summary":"Counsel days-to-relief (~70% trigger finger), flare, atrophy/depigmentation, infection/rupture return."}'::jsonb
WHERE id = 'tsi-aftercare' AND tree_id = 'tendon-sheath-injection';

-- Node: tsi-doc (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Procedure Note Template","body":"**Procedure:** Tendon-sheath corticosteroid injection — [first dorsal compartment, de Quervain / A1 pulley, trigger finger], [right/left] [thumb/finger].\n**Indication:** [de Quervain tenosynovitis (positive Finkelstein) / trigger finger (A1 nodule + triggering)]; infection/septic tenosynovitis excluded.\n**Consent:** Risks of flare, fat atrophy/depigmentation, tendon rupture, infection, and recurrence discussed; patient agrees.\n**Agent:** [Triamcinolone / methylprednisolone / dexamethasone] [dose] + lidocaine 1% ~[X] mL.\n**Technique:** 25-27 ga into the sheath; low-resistance free flow confirmed; needle did not move with passive tendon excursion; deposit kept off subcutaneous tissue.\n**Tolerance:** Tolerated well; no complications.\n**Disposition:** Discharged; [splint]; return precautions; hand-surgery follow-up if no improvement or recurrence.","citation":[2,3],"recommendation":"Document target, diagnosis, infection exclusion, agent/dose, sheath confirmation, dispo/referral.","confidence":"definitive","summary":"Note: target, diagnosis, infection excluded, agent/dose, sheath confirmation, dispo + referral."}'::jsonb
WHERE id = 'tsi-doc' AND tree_id = 'tendon-sheath-injection';

