-- Node: uls-sick-check (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Unilateral Leg Swelling — Sick Check First","body":"**A swollen leg is not just \"DVT vs cellulitis.\"** Before you settle on the common causes, exclude the limb- and life-threats that share the same presentation: a threatened limb (phlegmasia, acute ischemia, compartment syndrome), a necrotizing infection, and a systemic driver (right-heart failure, massive DVT with PE).\n\n**⚠️ 5 DO-NOT-MISS diagnoses**\n1. **DVT with PE** — a swollen calf plus pleuritic chest pain, dyspnea, or hypoxia is a pulmonary embolism until proven otherwise.\n2. **Phlegmasia cerulea dolens** — massive iliofemoral DVT: a tensely swollen, dusky/cyanotic, painful limb; venous gangrene and limb loss follow if not decompressed.\n3. **Necrotizing soft-tissue infection** — pain out of proportion, crepitus, dusky skin, systemic toxicity; a surgical emergency, not \"cellulitis.\"\n4. **Acute limb ischemia** — a cold, pale, pulseless, painful limb; can co-present with swelling. The 6 Ps; salvage is time-critical.\n5. **Compartment syndrome** — a tense compartment with pain on passive stretch, often after trauma/reperfusion; pressure kills muscle and nerve.\n\n**First 60 seconds:** vitals (fever/toxicity → screen sepsis with qSOFA in the toolbar), check the pulses and skin color/temperature of BOTH legs, feel the compartments, look for chest symptoms / hypoxia, and measure calf circumference. **A cold pulseless limb, a dusky tense limb, or pain out of proportion overrides the \"it’s probably a DVT\" reflex — work the limb-threat first.**","citation":[1,2,3,5,6,7],"next":"uls-triage","safetyLevel":"critical"}'::jsonb
WHERE id = 'uls-sick-check' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-pe-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Concurrent PE — Work It Up Now","body":"A swollen leg with chest symptoms or hypoxia is a **pulmonary embolism** until excluded. Open [PE Treatment](#/tree/pe-treatment) for the full pathway.\n\n**Next steps:**\n- Assess hemodynamic stability; **if unstable / massive PE, this is a resuscitation** (consider thrombolysis).\n- CT pulmonary angiography (or V/Q) to confirm; ECG, troponin, and echo help risk-stratify (RV strain).\n- **Start anticoagulation** unless contraindicated while the workup proceeds; do not wait for the leg ultrasound.\n- A confirmed DVT + PE is the same treatment thread — anticoagulate and risk-stratify.","citation":[6,9,14],"next":"uls-dvt-verdict","recommendation":"Screen/confirm PE (CTPA), assess stability (thrombolysis if unstable), start anticoagulation while working up; do not wait for leg US.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'uls-pe-verdict' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-rhf-entry (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Right-Heart Failure — Systemic Gate","body":"**Heart failure classically causes bilateral edema, but it can present asymmetrically** (dependent positioning, prior DVT, venous insufficiency, or unilateral lymphatic disease). Suspect a cardiac driver with dyspnea, orthopnea, a raised JVP, an S3, hepatomegaly, or a known cardiac history. **Do NOT anchor on \"cardiac edema\" and miss a superimposed DVT** — they coexist, and stasis in the failing patient raises DVT risk.","citation":[1,13],"options":[{"label":"Dyspnea / raised JVP / cardiac history + edema, DVT/limb-threat excluded","description":"Treat as right-heart failure","next":"uls-rhf-verdict","urgency":"urgent"},{"label":"No cardiopulmonary signs / not the picture","description":"RHF unlikely — move on","next":"uls-rhf-excluded","urgency":"routine"}],"summary":"Asymmetric edema can still be cardiac (dyspnea, raised JVP, S3); do not miss a superimposed DVT.","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-rhf-entry' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-rhf-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Right-Heart Failure — Treat the Pump","body":"Open [Right-Heart Failure](#/tree/right-heart-failure) and [CHF Exacerbation](#/tree/chf-exacerbation) for the full pathways.\n\n**Next steps:**\n- Work up the cardiac cause: ECG, chest imaging, BNP/NT-proBNP, troponin, and bedside/formal echo (RV size/function, valvular disease, pulmonary hypertension).\n- Treat congestion (diuresis) while respecting preload-dependent RV physiology; treat the underlying driver (ischemia, PE, pulmonary hypertension, valvular disease).\n- **Still exclude a concurrent DVT** if the swelling is asymmetric — a failing, immobile patient is prothrombotic.\n- Admit / cardiology as dictated by acuity and the underlying cause.","citation":[13],"recommendation":"Confirm and treat the cardiac cause (echo, diuresis, treat driver) while excluding a superimposed DVT in the asymmetric leg.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-rhf-verdict' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-rhf-excluded (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Right-Heart Failure — Unlikely","body":"No dyspnea, no raised JVP, and no cardiac history — a cardiac driver is unlikely for this asymmetric swelling.\n\nReturn to the hub for the benign mimics.","citation":[13],"next":"uls-triage","recommendation":"Cardiac cause unlikely without cardiopulmonary signs; proceed to the benign mimics.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-rhf-excluded' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-disposition (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Disposition","body":"Where does this patient go?","citation":[1,9],"options":[{"label":"Limb threat / necrotizing infection / massive DVT-PE / toxic","description":"OR / vascular / admit","next":"uls-dispo-admit","urgency":"critical"},{"label":"Uncomplicated DVT needing anticoagulation, or borderline","description":"Observe / short stay / start anticoagulation","next":"uls-dispo-observe","urgency":"urgent"},{"label":"Benign mimic / cellulitis suitable for outpatient care","description":"Discharge with follow-up","next":"uls-dispo-discharge","urgency":"routine"}],"summary":"OR/admit the limb-threats; observe/anticoagulate the DVTs and borderlines; discharge benign/cellulitis with follow-up."}'::jsonb
WHERE id = 'uls-disposition' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-dispo-admit (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Admit / OR","body":"**To the OR / admit** the limb- or life-threat.\n\n- **Acute limb ischemia → emergent revascularization** (embolectomy / thrombolysis / bypass) + heparin.\n- **Phlegmasia → heparin + catheter-directed thrombolysis/thrombectomy**, limb elevation, resuscitation.\n- **Necrotizing infection → emergent debridement** + broad-spectrum abx + resuscitation.\n- **Compartment syndrome → emergent fasciotomy.**\n- **Massive/high-risk DVT-PE → admit** for anticoagulation ± thrombolysis and monitoring.\n- Ongoing resuscitation, analgesia, and specialty (vascular / surgery / cardiology) management; ICU for unstable patients.","citation":[2,3,4,5,9],"recommendation":"OR/emergent intervention for ischemia / phlegmasia / necrotizing infection / compartment syndrome; admit high-risk DVT-PE; ICU if unstable.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'uls-dispo-admit' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-dispo-observe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Observe / Short Stay","body":"**Observation / short stay** for the borderline patient — e.g., a confirmed DVT started on anticoagulation who needs teaching and follow-up arranged, a limb where ischemia/compartment is not fully excluded and needs serial exams, or cellulitis borderline for outpatient failure.\n\n- Serial exams (pulses, compartments), repeat ultrasound if the picture changes, and specialist input before disposition.\n- Ensure reliable, timely follow-up and clear return precautions before any discharge; treat pain.","citation":[1,9],"recommendation":"Short observation + serial exams + specialist input; arrange anticoagulation follow-up, then admit or discharge with tight follow-up.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-dispo-observe' AND tree_id = 'unilateral-leg-swelling-hub';

